1	/**
2	 * MLflow tracing integration for Codex CLI.
3	 *
4	 * Two integration modes:
5	 *
6	 * 1. **Notify hook** (recommended): Codex passes turn data as a JSON CLI arg
7	 *    after each agent turn. Simple, no transcript parsing needed.
8	 *    Configured via `notify` in config.toml.
9	 *
10	 * 2. **Transcript parsing**: Reads the rollout JSONL file for richer data
11	 *    (tool calls, token usage). Used when transcript_path is available.
12	 *
13	 * References:
14	 * - Notify hook: developers.openai.com/codex/hooks
15	 * - Protocol types: github.com/openai/codex codex-rs/protocol/src/protocol.rs
16	 * - Rollout recorder: github.com/openai/codex codex-rs/rollout/src/recorder.rs
17	 */
18	
19	import {
20	  startSpan,
21	  flushTraces,
22	  InMemoryTraceManager,
23	  SpanStatusCode,
24	  SpanType,
25	  SpanAttributeKey,
26	  TraceMetadataKey,
27	  TokenUsageKey,
28	  type LiveSpan,
29	} from '@mlflow/core';
30	
31	import type {
32	  ChatMessage,
33	  EventMsgPayload,
34	  NotifyPayload,
35	  RolloutLine,
36	  ResponseItemPayload,
37	} from './types.js';
38	import {
39	  parseTimestampToNs,
40	  extractTextFromContent,
41	  getTokenUsage,
42	  getModel,
43	  buildToolResultMap,
44	  findTranscriptForThread,
45	  getLastTurnRecords,
46	  readTranscript,
47	} from './transcript.js';
48	
49	/**
50	 * Process a Codex notify hook payload and create an MLflow trace.
51	 *
52	 * The notify payload has the user prompt and assistant response directly,
53	 * so we create a simple AGENT → LLM trace. If a transcript file is found,
54	 * we also parse it for tool calls and token usage.
55	 */
56	export async function processNotify(payload: NotifyPayload): Promise<void> {
57	  // input-messages accumulates all prompts in the session; take only the last one
58	  const inputMessages = payload['input-messages'] ?? [];
59	  const userPrompt = inputMessages[inputMessages.length - 1] ?? '';
60	  const assistantResponse = payload['last-assistant-message'] ?? '';
61	  const sessionId = payload['thread-id'];
62	
63	  if (!userPrompt) {
64	    return;
65	  }
66	
67	  // Try to find and parse the transcript for richer data (tool calls, tokens)
68	  const transcriptPath = findTranscriptForThread(sessionId);
69	  let turnRecords: RolloutLine[] | null = null;
70	  let model = 'unknown';
71	
72	  if (transcriptPath) {
73	    const records = readTranscript(transcriptPath);
74	    if (records.length > 0) {
75	      turnRecords = getLastTurnRecords(records);
76	      model = getModel(records);
77	    }
78	  }
79	
80	  // Root span bracket: use task_started / task_complete from the transcript
81	  // so the root span covers the full turn. Without this, the root span would
82	  // only cover the hook's own wall-clock execution time (a few ms), which is
83	  // AFTER the transcript timestamps on the children. That makes the waterfall
84	  // scale to ~turn_duration + hook_delay with the root as a sliver at the
85	  // right edge. Opencode uses the same pattern with message.time.created /
86	  // .completed.
87	  const rootStartNs = turnRecords ? findTaskStartedNs(turnRecords) : null;
88	  const rootEndNs = turnRecords ? findTaskCompleteNs(turnRecords) : null;
89	
90	  // Create root AGENT span. Pass the user prompt as a raw string so MLflow
91	  // can auto-generate the request preview and the session view renders the
92	  // message cleanly.
93	  const rootSpan = startSpan({
94	    name: 'codex_conversation',
95	    spanType: SpanType.AGENT,
96	    inputs: userPrompt,
97	    attributes: { model },
98	    ...(rootStartNs != null ? { startTimeNs: rootStartNs } : {}),
99	  });
100	
101	  // If we have transcript data, create detailed child spans
102	  if (turnRecords && turnRecords.length > 0) {
103	    createChildSpans(rootSpan, turnRecords, model);
104	
105	    const tokenUsage = getTokenUsage(turnRecords);
106	    if (tokenUsage) {
107	      rootSpan.setAttribute(SpanAttributeKey.TOKEN_USAGE, {
108	        [TokenUsageKey.INPUT_TOKENS]: tokenUsage.input_tokens,
109	        [TokenUsageKey.OUTPUT_TOKENS]: tokenUsage.output_tokens,
110	        [TokenUsageKey.TOTAL_TOKENS]: tokenUsage.total_tokens,
111	      });
112	    }
113	  } else {
114	    // Fallback: create a simple LLM span from the notify data using the same
115	    // OpenAI chat format the transcript path produces.
116	    const llmSpan = startSpan({
117	      name: 'llm_call',
118	      parent: rootSpan,
119	      spanType: SpanType.LLM,
120	      inputs: {
121	        model,
122	        messages: [{ role: 'user', content: userPrompt }],
123	      },
124	      attributes: { model },
125	    });
126	    llmSpan.end({
127	      outputs: {
128	        choices: [{ message: { role: 'assistant', content: assistantResponse } }],
129	      },
130	    });
131	  }
132	
133	  // Attach session/user metadata to the trace. We use InMemoryTraceManager
134	  // directly because `updateCurrentTrace()` requires an active OTel span
135	  // context, which hook-based integrations don't have — spans are created
136	  // via `startSpan()` without OTel context propagation.
137	  const traceId = rootSpan.traceId;
138	  if (traceId) {
139	    const traceManager = InMemoryTraceManager.getInstance();
140	    const trace = traceManager.getTrace(traceId);
141	    if (trace) {
142	      trace.info.traceMetadata = {
143	        ...trace.info.traceMetadata,
144	        [TraceMetadataKey.TRACE_SESSION]: sessionId,
145	        [TraceMetadataKey.TRACE_USER]: process.env.USER ?? '',
146	      };
147	    }
148	  }
149	
150	  rootSpan.end({
151	    outputs: assistantResponse,
152	    ...(rootEndNs != null ? { endTimeNs: rootEndNs } : {}),
153	  });
154	
155	  await flushTraces();
156	}
157	
158	/**
159	 * Reconstruct OpenAI chat-format message history from response_items preceding
160	 * the current index. Used to populate LLM span inputs so the MLflow Chat view
161	 * shows the full conversation context that led up to each assistant call.
162	 *
163	 * Maps Codex's Responses-API-style records to standard chat messages:
164	 * - `message` (user/assistant/system) → `{role, content}`
165	 * - `function_call` → assistant message with `tool_calls: [{id, type, function}]`
166	 * - `function_call_output` → `{role: 'tool', tool_call_id, content}`
167	 */
168	export function reconstructMessages(
169	  responseItems: RolloutLine[],
170	  uptoIndex: number,
171	): ChatMessage[] {
172	  const messages: ChatMessage[] = [];
173	  for (let i = 0; i < uptoIndex; i++) {
174	    const payload = responseItems[i].payload as ResponseItemPayload;
175	
176	    if (payload.type === 'message') {
177	      const text = extractTextFromContent(payload.content);
178	      if (!text.trim()) {
179	        continue;
180	      }
181	      if (payload.role === 'user' || payload.role === 'assistant') {
182	        messages.push({ role: payload.role, content: text });
183	      } else if (payload.role === 'developer') {
184	        // Codex uses "developer" for system-style instructions; render as system
185	        messages.push({ role: 'system', content: text });
186	      }
187	    } else if (payload.type === 'function_call') {
188	      messages.push({
189	        role: 'assistant',
190	        content: null,
191	        tool_calls: [
192	          {
193	            id: payload.call_id ?? '',
194	            type: 'function',
195	            function: {
196	              name: payload.name ?? 'unknown',
197	              arguments: payload.arguments ?? '{}',
198	            },
199	          },
200	        ],
201	      });
202	    } else if (payload.type === 'function_call_output') {
203	      messages.push({
204	        role: 'tool',
205	        tool_call_id: payload.call_id ?? '',
206	        content: payload.output ?? '',
207	      });
208	    }
209	  }
210	  return messages;
211	}
212	
