1	import { init } from '@mlflow/core';
2	
3	let initialized = false;
4	
5	/**
6	 * Initialize the MLflow SDK with tracking URI and experiment settings.
7	 * No-ops if already initialized or if required env vars are missing.
8	 */
9	export function ensureInitialized(): boolean {
10	  if (initialized) {
11	    return true;
12	  }
13	
14	  const trackingUri = process.env.MLFLOW_TRACKING_URI;
15	  if (!trackingUri) {
16	    console.error('[mlflow] MLFLOW_TRACKING_URI is not set');
17	    return false;
18	  }
19	
20	  init({
21	    trackingUri,
22	    experimentId: process.env.MLFLOW_EXPERIMENT_ID,
23	  });
24	
25	  initialized = true;
26	  return true;
