[metadata] {"type": "create", "filePath": "/workspace/repo/libs/typescript/integrations/qwen-code/src/types.ts", "content": "/**
 * Types for Qwen Code CLI session transcripts.
 *
 * Qwen Code (a fork of Gemini CLI) records each conversation as a JSONL file
 * where every line is a `ChatRecord`. Records use the Gemini content format:
 * a `message` with a `role` and an array of `parts`, where each part is either
 * a text part, a functionCall part, or a functionResponse part.
 *
 * Reference: github.com/QwenLM/qwen-code
 */

/**
 * A single message part in the Gemini content format.
 *
 * - Text part: `{ text: string; thought?: boolean }` — `thought` marks internal
 *   reasoning that should not be surfaced as user-visible output.
 * - FunctionCall part: a model request to invoke a tool.
 * - FunctionResponse part: the tool's response, echoed back into the history.
 */
export type GeminiPart =
  | { text: string; thought?: boolean }
  | { functionCall: { id: string; name: string; args?: Record<string, any> } }
  | { functionResponse: { id: string; name: string; response: any } };

/**
 * The structured message on a ChatRecord: a role plus an ordered list of parts.
 */
export interface GeminiMessage {
  role: string;
  parts: GeminiPart[];
}

/**
 * A single line in a Qwen Code session transcript JSONL file.
 */
export interface ChatRecord {
  uuid: string;
  parentUuid: string | null;
  sessionId: string;
  timestamp: string;
  type: 'user' | 'assistant' | 'system' | 'tool_result';
  message?: GeminiMessage | string;
  toolCallResult?: {
    callId: string;
    status: string;
    resultDisplay?: any;
  };
  usageMetadata?: {
    promptTokenCount: number;
    candidatesTokenCount: number;
    totalTokenCount: number;
  };
  model?: string;
}

/**
 * OpenAI chat-format tool call, used on assistant messages.
 */
export interface OpenAIToolCall {
  id: string;
  type: 'function';
  function: {
    name: string;
    arguments: string;
  };
}

/**
 * OpenAI chat-completion message used in LLM span inputs. Matches the message
 * structure the MLflow UI Chat view renders.
 */
export interface OpenAIMessage {
  role: 'user' | 'assistant' | 'system' | 'tool';
  content: string | null;
  tool_calls?: OpenAIToolCall[];
  tool_call_id?: string;
}
