[metadata] {"type": "create", "filePath": "/workspace/repo/libs/typescript/integrations/qwen-code/src/transcript.ts", "content": "/**
 * Transcript parsing utilities for Qwen Code session JSONL files.
 *
 * Each line in a transcript is a `ChatRecord`. Assistant records carry a
 * `message` in Gemini content format (a `parts` array of text / functionCall /
 * functionResponse parts). Tool results are recorded as separate `tool_result`
 * records keyed by the originating function call's id.
 */

import { readFileSync } from 'node:fs';
import type { ChatRecord, GeminiPart } from './types.js';

export const NANOSECONDS_PER_MS = 1e6;

/**
 * Read and parse a Qwen Code JSONL transcript file into ChatRecord objects.
 */
export function readTranscript(path: string): ChatRecord[] {
  const content = readFileSync(path, 'utf-8');
  return content
    .split('\n')
    .filter((line) => line.trim())
    .map((line) => JSON.parse(line) as ChatRecord);
}

/**
 * Parse an ISO 8601 timestamp string to nanoseconds since the Unix epoch
 * (epoch milliseconds * 1,000,000). Returns null for null, undefined, or
 * empty-string input.
 */
export function parseTimestampToNs(timestamp: string | null | undefined): number | null {
  if (!timestamp) {
    return null;
  }
  const ms = new Date(timestamp).getTime();
  if (isNaN(ms)) {
    return null;
  }
  return ms * NANOSECONDS_PER_MS;
}

/**
 * Type guard: true when a GeminiPart is a text part (has a `text` property).
 */
export function isTextPart(
  part: GeminiPart,
): part is { text: string; thought?: boolean } {
  return part != null && typeof part === 'object' && 'text' in part;
}

/**
 * Type guard: true when a GeminiPart is a functionCall part (has a
 * `functionCall` property).
 */
export function isFunctionCallPart(
  part: GeminiPart,
): part is { functionCall: { id: string; name: string; args?: Record<string, any> } } {
  return part != null && typeof part === 'object' && 'functionCall' in part;
}

/**
 * Extract the text content of a ChatRecord's message.
 *
 * Joins all text parts with a newline. Thought parts (`thought === true`) are
 * excluded by default and included only when `includeThoughts` is true. A plain
 * string message is returned as-is. functionCall and functionResponse parts
 * contribute no text and are skipped.
 */
export function getMessageText(record: ChatRecord, includeThoughts = false): string {
  const message = record.message;
  if (!message) {
    return '';
  }
  if (typeof message === 'string') {
    return message;
  }
  const parts = message.parts;
  if (!Array.isArray(parts)) {
    return '';
  }
  return parts
    .filter(isTextPart)
    .filter((part) => includeThoughts || !part.thought)
    .map((part) => part.text)
    .join('\n');
}

/**
 * Extract all functionCall parts from a ChatRecord's message. Returns an empty
 * array for records with no message or no functionCall parts.
 */
export function getFunctionCalls(
  record: ChatRecord,
): Array<{ id: string; name: string; args?: Record<string, any> }> {
  const message = record.message;
  if (!message || typeof message === 'string') {
    return [];
  }
  const parts = message.parts;
  if (!Array.isArray(parts)) {
    return [];
  }
  return parts.filter(isFunctionCallPart).map((part) => ({
    id: part.functionCall.id,
    name: part.functionCall.name,
    args: part.functionCall.args,
  }));
}

/**
 * Build a Map from tool call id to its `tool_result` record. Only tool_result
 * records are included; other record types are skipped.
 */
export function buildToolResultMap(records: ChatRecord[]): Map<string, ChatRecord> {
  const map = new Map<string, ChatRecord>();
  for (const record of records) {
    if (record.type === 'tool_result' && record.toolCallResult?.callId) {
      map.set(record.toolCallResult.callId, record);
    }
  }
  return map;
}

/**
 * Normalize a resultDisplay value to a string. String values pass through
 * unchanged, objects are JSON.stringified, and null/undefined become an empty
 * string.
 */
export function formatResultDisplay(display: any): string {
  if (display === null || display === undefined) {
    return '';
  }
  if (typeof display === 'string') {
    return display;
  }
  return JSON.stringify(display);
}

/**
 * Extract the tool output from a tool_result record.
 *
 * Prefers `toolCallResult.resultDisplay` (passed through formatResultDisplay).
 * When resultDisplay is absent, falls back to JSON.stringify of the
 * functionResponse.response found in the record's message parts. Returns an
 * empty string when neither is available.
 */
export function getToolOutput(record: ChatRecord): string {
  const resultDisplay = record.toolCallResult?.resultDisplay;
  if (resultDisplay !== null && resultDisplay !== undefined) {
    return formatResultDisplay(resultDisplay);
  }

  const message = record.message;
  if (message && typeof message !== 'string' && Array.isArray(message.parts)) {
    for (const part of message.parts) {
      if (part != null && typeof part === 'object' && 'functionResponse' in part) {
        return JSON.stringify(part.functionResponse.response);
      }
    }
  }
  return '';
}

/**
 * Return the records belonging to the last turn: a slice starting at the last
 * record whose type is 'user' and continuing to the end of the array. Returns
 * the full array when there is no user record.
 */
export function getLastTurnRecords(records: ChatRecord[]): ChatRecord[] {
  let lastUserIndex = -1;
  for (let i = 0; i < records.length; i++) {
    if (records[i].type === 'user') {
      lastUserIndex = i;
    }
  }
  if (lastUserIndex === -1) {
    return records;
  }
  return records.slice(lastUserIndex);
}

/**
 * Extract token counts from a usageMetadata object, mapping promptTokenCount to
 * `input`, candidatesTokenCount to `output`, and totalTokenCount to `total`.
 * Returns null when the argument is undefined or missing.
 */
export function getTokenUsage(
  usageMetadata: any,
): { input: number; output: number; total: number } | null {
  if (!usageMetadata) {
    return null;
  }
  return {
    input: usageMetadata.promptTokenCount,
    output: usageMetadata.candidatesTokenCount,
    total: usageMetadata.totalTokenCount,
  };
}
