[metadata] {"type": "create", "filePath": "/workspace/repo/libs/typescript/integrations/qwen-code/src/tracing.ts", "content": "/**
 * MLflow tracing integration for Qwen Code CLI.
 *
 * Reads a Qwen Code session JSONL transcript and converts it into an MLflow
 * trace:
 *
 * - an AGENT root span (`qwen_code_conversation`) covering the whole session,
 * - one LLM span (`llm_call`) per assistant record, and
 * - one TOOL span (`tool_<name>`) per functionCall part on an assistant record.
 *
 * LLM span inputs/outputs use the OpenAI chat-completion format so the MLflow
 * Chat view renders the reconstructed conversation history cleanly.
 */

import {
  startSpan,
  flushTraces,
  InMemoryTraceManager,
  SpanStatusCode,
  SpanType,
  SpanAttributeKey,
  TraceMetadataKey,
  TokenUsageKey,
} from '@mlflow/core';

import type { ChatRecord, OpenAIMessage } from './types.js';
import {
  parseTimestampToNs,
  getMessageText,
  getFunctionCalls,
  buildToolResultMap,
  formatResultDisplay,
  getToolOutput,
  readTranscript,
} from './transcript.js';

/**
 * Reconstruct the OpenAI-format chat message history for the records preceding
 * `targetIndex`. Used to populate LLM span inputs so the Chat view shows the
 * full context that led up to each assistant call.
 *
 * - user record → `{ role: 'user', content }`
 * - assistant record with functionCall parts → `{ role: 'assistant',
 *   content: null, tool_calls: [...] }`
 * - assistant record with only text → `{ role: 'assistant', content }`
 *   (thought parts excluded)
 * - tool_result record → `{ role: 'tool', tool_call_id, content }`
 * - system record with a message → `{ role: 'system', content }`
 * - system record without a message → skipped
 */
export function reconstructMessages(
  records: ChatRecord[],
  targetIndex: number,
): OpenAIMessage[] {
  const messages: OpenAIMessage[] = [];

  for (let i = 0; i < targetIndex; i++) {
    const record = records[i];

    if (record.type === 'user') {
      messages.push({ role: 'user', content: getMessageText(record) });
    } else if (record.type === 'assistant') {
      const functionCalls = getFunctionCalls(record);
      if (functionCalls.length > 0) {
        messages.push({
          role: 'assistant',
          content: null,
          tool_calls: functionCalls.map((fc) => ({
            id: fc.id,
            type: 'function',
            function: { name: fc.name, arguments: JSON.stringify(fc.args ?? {}) },
          })),
        });
      } else {
        messages.push({ role: 'assistant', content: getMessageText(record) });
      }
    } else if (record.type === 'tool_result') {
      messages.push({
        role: 'tool',
        tool_call_id: record.toolCallResult?.callId ?? '',
        content: getToolOutput(record),
      });
    } else if (record.type === 'system') {
      if (record.message) {
        messages.push({ role: 'system', content: getMessageText(record) });
      }
      // system records without a message carry no content and are skipped
    }
  }

  return messages;
}

/**
 * Read a Qwen Code transcript and emit an MLflow trace.
 *
 * When `transcriptPath` is null, returns immediately without creating any spans
 * or flushing. Otherwise creates the AGENT root span, LLM spans, and TOOL spans
 * described in the module docstring, attaches session/token metadata, and
 * flushes the trace.
 */
export async function processTranscript(
  transcriptPath: string | null,
  sessionId?: string,
): Promise<void> {
  if (transcriptPath == null) {
    return;
  }

  const records = readTranscript(transcriptPath);
  const toolResultMap = buildToolResultMap(records);

  const assistantRecords = records.filter((r) => r.type === 'assistant');
  const firstUserRecord = records.find((r) => r.type === 'user');
  const lastAssistantRecord =
    assistantRecords.length > 0 ? assistantRecords[assistantRecords.length - 1] : undefined;

  const userPrompt = firstUserRecord ? getMessageText(firstUserRecord) : '';
  const finalAssistantText = lastAssistantRecord ? getMessageText(lastAssistantRecord) : '';

  const rootStartNs = firstUserRecord ? parseTimestampToNs(firstUserRecord.timestamp) : null;
  const rootEndNs = lastAssistantRecord
    ? parseTimestampToNs(lastAssistantRecord.timestamp)
    : null;

  // Root AGENT span. The user prompt is passed as a raw string so MLflow can
  // auto-generate the request preview and render the session view cleanly.
  const rootSpan = startSpan({
    name: 'qwen_code_conversation',
    spanType: SpanType.AGENT,
    inputs: userPrompt,
    ...(rootStartNs != null ? { startTimeNs: rootStartNs } : {}),
  });

  for (let i = 0; i < records.length; i++) {
    const record = records[i];
    if (record.type !== 'assistant') {
      continue;
    }

    const assistantNs = parseTimestampToNs(record.timestamp);
    const prevRecord = records[i - 1];
    const prevNs = prevRecord ? parseTimestampToNs(prevRecord.timestamp) : null;
    const model = record.model ?? 'unknown';

    // LLM span: from the preceding record's timestamp to this record's own.
    const llmSpan = startSpan({
      name: 'llm_call',
      parent: rootSpan,
      spanType: SpanType.LLM,
      inputs: { model, messages: reconstructMessages(records, i) },
      attributes: { model },
      ...(prevNs != null ? { startTimeNs: prevNs } : {}),
    });

    if (record.usageMetadata) {
      llmSpan.setAttribute(SpanAttributeKey.TOKEN_USAGE, {
        [TokenUsageKey.INPUT_TOKENS]: record.usageMetadata.promptTokenCount,
        [TokenUsageKey.OUTPUT_TOKENS]: record.usageMetadata.candidatesTokenCount,
        [TokenUsageKey.TOTAL_TOKENS]: record.usageMetadata.totalTokenCount,
      });
    }

    llmSpan.end({
      outputs: {
        choices: [{ message: { role: 'assistant', content: getMessageText(record) } }],
      },
      ...(assistantNs != null ? { endTimeNs: assistantNs } : {}),
    });

    // TOOL span per functionCall part on this assistant record.
    for (const fc of getFunctionCalls(record)) {
      const resultRecord = toolResultMap.get(fc.id);
      const toolEndNs = resultRecord ? parseTimestampToNs(resultRecord.timestamp) : assistantNs;

      const toolSpan = startSpan({
        name: `tool_${fc.name}`,
        parent: rootSpan,
        spanType: SpanType.TOOL,
        inputs: fc.args,
        attributes: { tool_id: fc.id },
        ...(assistantNs != null ? { startTimeNs: assistantNs } : {}),
      });

      // Only failed/cancelled tool calls get an explicit status; successful
      // calls stay in the default (unset) state.
      if (resultRecord?.toolCallResult?.status === 'cancelled') {
        toolSpan.setStatus(
          SpanStatusCode.ERROR,
          `Tool call ${fc.name} was cancelled`,
        );
      }

      toolSpan.end({
        outputs: {
          result: formatResultDisplay(resultRecord?.toolCallResult?.resultDisplay),
        },
        ...(toolEndNs != null ? { endTimeNs: toolEndNs } : {}),
      });
    }
  }

  // Root token usage: input is the LAST assistant call's prompt token count
  // (prompt tokens are cumulative in Gemini, so the last call already reflects
  // the full context), output is the sum of generated tokens across all calls.
  let lastPromptTokens = 0;
  let summedCandidateTokens = 0;
  for (const record of assistantRecords) {
    if (record.usageMetadata) {
      lastPromptTokens = record.usageMetadata.promptTokenCount ?? lastPromptTokens;
      summedCandidateTokens += record.usageMetadata.candidatesTokenCount ?? 0;
    }
  }
  rootSpan.setAttribute(SpanAttributeKey.TOKEN_USAGE, {
    [TokenUsageKey.INPUT_TOKENS]: lastPromptTokens
